WITH valid AS (SELECT *, ROUND(quantity * 1.07, 2) AS quantity_adjusted, CEIL(quantity) AS quantity_whole FROM inventory WHERE quantity BETWEEN 117 AND 123), with_windows AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY quantity_whole, id) AS event_seq, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY quantity DESC, id) AS event_seq_2 FROM valid), enriched AS (SELECT id, store_id, product_id, quantity, last_restock, quantity_adjusted, quantity_whole, event_seq, event_seq_2, SUM(quantity_whole) OVER (PARTITION BY product_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_quantity_whole, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY last_restock DESC, id) AS row_seq, FIRST_VALUE(quantity_adjusted) IGNORE NULLS OVER (ORDER BY event_seq_2, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_quantity_adjusted, AVG(quantity) OVER (PARTITION BY product_id, store_id ORDER BY quantity_whole, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS quantity_avg_2_prior, SUM(quantity_whole) OVER (PARTITION BY product_id ORDER BY quantity_adjusted, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_quantity_whole_2 FROM with_windows), metrics AS (SELECT *, NTILE(4) OVER (PARTITION BY product_id, store_id ORDER BY first_known_quantity_adjusted DESC, id) AS first_known_quantity_adjusted_bucket, COUNT(cumulative_quantity_whole) OVER (PARTITION BY store_id) AS store_id_count_cumulative_quantity_whole, NTILE(4) OVER (PARTITION BY product_id ORDER BY cumulative_quantity_whole, id) AS cumulative_quantity_whole_bucket, FIRST_VALUE(cumulative_quantity_whole, TRUE) OVER (PARTITION BY store_id ORDER BY row_seq, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_cumulative_quantity_whole FROM enriched), totals AS (SELECT store_id, STDDEV_SAMP(quantity) AS quantity_stddev, BIT_AND(quantity) AS quantity_bit_and, PERCENTILE_APPROX(first_known_quantity_adjusted, ARRAY(0.25, 0.5, 0.75)) AS first_known_quantity_adjusted_quartiles FROM metrics GROUP BY store_id HAVING quantity_bit_and >= 1) SELECT store_id, quantity_bit_and, first_known_quantity_adjusted_quartiles FROM totals ORDER BY store_id NULLS FIRST, quantity_bit_and DESC LIMIT 10
